/* HEXA BATTLEGROUNDS upgrade — PART 8 OF 38. Only for databases that already ran setup part-01…; Run in order. Safe to re-run. */ create or replace function _red_spawn(p_arena uuid, p_x float8 default null, p_y float8 default null) returns jsonb language plpgsql as $$ declare a arenas; c float8[]; tr float8[]; rr float8; x float8; y float8; i int; ang float8; mag float8; begin select * into a from arenas where id = p_arena for update; if a.phase <> 'play' then raise exception 'WRONG_PHASE'; end if; if a.red_at is not null then raise exception 'RED_ZONE_ACTIVE'; end if; c := _zone_circle(a.event_id, a.zone_stage); tr := _loc_xy('tr14'); rr := _cfg(a.event_id, 'red_radius') / 1000.0; if p_x is not null then x := greatest(0.04, least(0.96, p_x)); y := greatest(0.04, least(0.96, p_y)); else for i in 1..30 loop ang := random() * 2 * pi(); mag := sqrt(random()) * greatest(0.01, c[3] - rr * 0.5); x := greatest(0.05, least(0.95, c[1] + cos(ang) * mag)); y := greatest(0.05, least(0.95, c[2] + sin(ang) * mag)); exit when sqrt((x - tr[1]) ^ 2 + (y - tr[2]) ^ 2) > rr + 0.05; end loop; end if; update arenas set red_x = x, red_y = y, red_r = rr, red_at = now() + _secs(_cfg(a.event_id, 'red_warning')) where id = p_arena; perform _feed(p_arena, 'redzone.warning', jsonb_build_object('location', _loc_at(a.event_id, x, y))); perform _zone_publish(p_arena); perform _ping_arena(p_arena, 'redzone'); return jsonb_build_object('x', x, 'y', y, 'r', rr); end $$; create or replace function _red_strike(p_arena uuid) returns void language plpgsql as $$ declare a arenas; r teams; xy float8[]; v_hits int[] := '{}'; v_dmg int; d int; begin select * into a from arenas where id = p_arena for update; if a.red_at is null then return; end if; v_dmg := _cfg(a.event_id, 'red_damage'); for r in select * from teams where arena_id = p_arena and ready and state <> 'recovery' loop xy := _team_xy(r); if sqrt((xy[1] - a.red_x) ^ 2 + (xy[2] - a.red_y) ^ 2) <= a.red_r then d := _damage(r.id, v_dmg, 'redzone', 'rz-' || extract(epoch from a.red_at)::bigint, 'Caught in a red zone'); v_hits := v_hits || r.number; perform _ping_team(r.id, 'redzone'); end if; end loop; update arenas set red_x = null, red_y = null, red_r = null, red_at = null, last_red_at = now() where id = p_arena; perform _feed(p_arena, 'redzone.strike', jsonb_build_object('hits', to_jsonb(v_hits))); perform _zone_publish(p_arena); perform _ping_arena(p_arena, 'redzone'); end $$; create or replace function captain_steer(p_token text, p_x float8, p_y float8) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; cur float8[]; dt float8; maxd float8; d float8; nx float8; ny float8; v_loc text; v_others int; v_ping boolean; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state = 'recovery' then raise exception 'BUSY'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind = 'battle') then raise exception 'IN_BATTLE'; end if; if p_x is null or p_y is null or p_x = 'NaN'::float8 or p_y = 'NaN'::float8 or abs(p_x) = 'Infinity'::float8 or abs(p_y) = 'Infinity'::float8 then raise exception 'BAD_REQUEST'; end if; cur := _team_xy(t); dt := least(4, greatest(0, extract(epoch from now() - coalesce(case when t.state = 'traveling' then now() else t.pos_at end, now() - interval '1 second')))); if t.state = 'traveling' then dt := 0.25; end if; maxd := (_cfg(t.event_id, 'move_speed') / 1000.0) * dt * 1.25 + 0.003; nx := greatest(0.035, least(0.965, p_x)); ny := greatest(0.035, least(0.965, p_y)); d := sqrt((nx - cur[1]) ^ 2 + (ny - cur[2]) ^ 2); if d > maxd then nx := cur[1] + (nx - cur[1]) * maxd / d; ny := cur[2] + (ny - cur[2]) * maxd / d; end if; v_loc := _loc_at(t.event_id, nx, ny); if v_loc is distinct from t.location_id then update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind in ('mission', 'relay', 'airdrop') and sync_round_id is null; end if; v_ping := v_loc is distinct from t.location_id or t.last_steer_ping is null or t.last_steer_ping < now() - interval '2 seconds'; update teams set pos_x = nx, pos_y = ny, pos_at = now(), dropped = true, location_id = v_loc, state = 'idle', travel_to = null, travel_from = null, travel_started_at = null, travel_arrive_at = null, visit_missions = case when v_loc is distinct from t.location_id then 0 else visit_missions end, last_steer_ping = case when v_ping then now() else last_steer_ping end where id = t.id; if v_loc is not null and v_loc is distinct from t.location_id then if t.jammed_until is null or t.jammed_until < now() then perform _feed(t.arena_id, 'squad.arrived', jsonb_build_object('team', t.number, 'location', v_loc)); end if; select count(*) into v_others from teams x where x.arena_id = t.arena_id and x.ready and x.id <> t.id and x.location_id = v_loc; if v_others > 0 then perform _feed(t.arena_id, 'encounter.detected', jsonb_build_object('location', v_loc, 'squads', v_others + 1)); perform _ping_arena(t.arena_id, 'encounter'); end if; end if; if v_ping then perform _ping_team(t.id, 'move'); end if; return jsonb_build_object('x', nx, 'y', ny, 'location', v_loc, 'clamped', d > maxd); end $$; create or replace function _respawn(p_team uuid, p_reason text) returns void language plpgsql as $$ declare t teams; a arenas; xy float8[]; v_safe text; begin select * into t from teams where id = p_team for update; if t.state <> 'recovery' then return; end if; update mission_instances set status = case when status = 'active' then 'expired' else status end where team_id = p_team and kind = 'recovery' and status = 'active'; update teams set state = 'idle', recovery_deadline = null, hp = _cfg(t.event_id, 'hp_respawn'), protected_until = now() + _secs(_cfg(t.event_id, 'protect_seconds')) where id = p_team; select * into a from arenas where id = t.arena_id; xy := _team_xy(t); if a.phase = 'play' and not _in_circle(_zone_circle(a.event_id, a.zone_stage), xy[1], xy[2]) then v_safe := _nearest_safe_xy(a.event_id, a.zone_stage, xy[1], xy[2]); if v_safe is not null then update teams set location_id = v_safe, pos_x = (_loc_xy(v_safe))[1], pos_y = (_loc_xy(v_safe))[2], pos_at = now(), visit_missions = 0 where id = p_team; end if; end if; perform _feed(t.arena_id, 'recovery.completed', jsonb_build_object('team', t.number, 'how', p_reason)); perform _ping_team(p_team, 'recovery'); end $$;
